fn extract(condition: Vec<bool>, arr: Vec<f32>) -> Vec<f32> {
    // The two input vectors must have the same length.
    assert_eq!(condition.len(), arr.len(),
               "Mask and data array must have the same length");

    // Zip the mask and the data, filter by mask, and collect the selected values.
    condition
        .into_iter()
        .zip(arr.into_iter())
        .filter_map(|(keep, value)| if keep { Some(value) } else { None })
        .collect()
}

